mapper.select:


    del_flag = '0'

        and stat_month = #{statMonth}


        and enterprise_id = #{enterpriseId}


        and enterprise_name like concat('%', #{enterpriseName}, '%')


        and region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}

        and credit_level = #{creditLevel}


        and color_code = #{colorCode}


        and warning_status = #{warningStatus}


order by stat_month desc, total_score desc, score_id desc


where stat_month = #{statMonth}
  and enterprise_id = #{enterpriseId}
  and del_flag = '0'
limit 1


where stat_month = #{statMonth}
  and del_flag = '0'
order by total_score desc, evaluate_time asc, score_id asc

select count(1)
from t_labor_contract
where del_flag = '0'
  and start_date <= #{periodEnd}
  and end_date >= #{periodStart}
  and (dispatch_enterprise_id = #{enterpriseId} or employer_enterprise_id = #{enterpriseId})

select count(1)
from t_social_base_compare
where del_flag = '0'
  and stat_month = #{statMonth}
  and enterprise_id = #{enterpriseId}

select count(1)
from t_social_base_compare
where del_flag = '0'
  and stat_month = #{statMonth}
  and compare_result = '1'
  and enterprise_id = #{enterpriseId}

select count(1)
from t_tax_compare
where del_flag = '0'
  and stat_month = #{statMonth}
  and enterprise_id = #{enterpriseId}

select count(1)
from t_tax_compare
where del_flag = '0'
  and stat_month = #{statMonth}
  and compare_result = '1'
  and enterprise_id = #{enterpriseId}

select count(1)
from t_uninsured_list
where del_flag = '0'
  and stat_month = #{statMonth}
  and enterprise_id = #{enterpriseId}

select count(1)
from t_injury_event
where del_flag = '0'
